/*
 * languages.js — gemeinsame Übersetzungsbibliothek für die Kartenwerkstatt.
 * Wird sowohl von MAP.html (Kartengenerator) als auch von index.html (Startseite) genutzt.
 *
 * Schlüssel für MAP.html: title, subtitle, generateBtn, downloadBtn, toggleSettingsBtn,
 *   copySettingsBtn, shareToggleBtn, applyPasteSettingsBtn, settingsCopied, settingsCopyError,
 *   pasteSettingsPrompt, pasteSettingsError, lblSeed, grpCastles, lblMainCastle, lblOutposts,
 *   lblNoOutposts, grpTerrain, lblMountains, lblSea, lblForest, lblDesert, grpRiver,
 *   lblGenerateRiver, lblBridges, grpMap, lblFields, grpMarkers, lblActionFields, lblMerchant,
 *   footer, mapWord, fieldsWord, pngError, options{...}
 * Schlüssel für index.html: dir, pageTitle, heading, indexSubtitle, indexFooter, description, buttonText, playerButtonText
 * Schlüssel für player.html: playerHeading, playerSubtitle, playerLblName, playerLblEpithet, playerLblRank,
 *   playerLblIcon, playerHintEmoji (HTML, enthält <kbd> Tags), playerLblAbility, playerBtnBold, playerBtnItalic,
 *   playerBtnUnderline, playerLblStrengthCount, playerLblWillCount, playerLblAccentColor, playerToggleStorage,
 *   playerExportBtn, playerTrackStrength, playerTrackWill, playerPouchText, playerBrand, playerExportCreating,
 *   playerExportSaved, playerExportError, playerColorGold, playerColorCrimson, playerColorForest, playerColorAzure,
 *   playerColorPurple
 * Schlüssel für player.html Klassen-Feature: playerLblClass, playerClassNone, sowie pro Klasse
 *   (mage/knight/goblin/elf/dwarf/barbarian/rogue/cleric) je ein …Name und …Perk Key
 *   (z.B. playerClassMageName, playerClassMagePerk).
 * (playerHintEmoji nutzt data-i18n-html statt data-i18n, da es <kbd>-Tags enthält.
 *  4 Sprachen ohne eigene player.html-Übersetzung (aus der urspr. 44er MAP-Liste: mr, sq, ta, te)
 *  nutzen für player*-Felder ein Englisch-Fallback, ebenso wie zuvor schon für die index*-Felder.)
 */
