    "playerClassPaladinPerk": "पैलादिन अपने हथियार को पवित्र ऊर्जा से भर देता है और अतिरिक्त प्रकाश-क्षति पहुँचाता है। मृतात्माओं और राक्षसों को दोगुना अतिरिक्त क्षति होती है।",
    "playerClassRangerPerk": "रेंजर एक शत्रु को चिह्नित करके उसकी कमज़ोरियाँ पहचान लेता है। उस लक्ष्य पर उसके अगले हमले अधिक सटीक होते हैं और ज़्यादा क्षति पहुँचाते हैं।",
