    "playerClassRangerPerk": "வனக்காவலர் ஒரு எதிரியைக் குறிவைத்து அவனது பலவீனங்களை அறிகிறார். அந்த இலக்குக்கு எதிரான அவரது அடுத்த தாக்குதல்கள் மிகத் துல்லியமாகவும் அதிக சேதம் விளைவிப்பதாகவும் இருக்கும்.",
    "playerClassDruidPerk": "நிலத்திலிருந்து வேர்கள் வெடித்து எழுந்து எதிரிகளைப் பிடித்து வைத்து, அவர்களுக்கு இயற்கை சேதத்தை ஏற்படுத்துகின்றன.",
    "playerClassBardPerk": "பாணர் ஒரு மாயாஜால இசையை வாசித்து தன் கூட்டாளிகளை வலுப்படுத்தி அவர்களுக்குப் புதிய துணிவைத் தருகிறார்.",
    "playerClassMonkPerk": "துறவி மின்னல் வேகத் தாக்குதலைச் செலுத்தி, பின்னர் வாய்ப்புத் தாக்குதல்களைத் தூண்டாமல் நெருக்கமான சண்டை எல்லையிலிருந்து விலகிச் செல்லலாம்.",
    "playerClassWarlockPerk": "வார்லாக் எதிரியின் மீது இருண்ட மாயாஜாலக் கோளத்தை எறிந்து அவனது உயிர்ச்சக்தியைப் பலவீனப்படுத்துகிறான்.",
    "playerClassNecromancerPerk": "நெக்ரோமான்சர் தனக்காகப் போரிடும் ஒரு எலும்புக்கூட்டை வரவழைத்து, எதிரிகளைப் பிடித்து வைத்து, தாக்குதல்களைத் தடுக்கிறான்.",
    "playerClassAlchemistPerk": "நாளுக்கு ஒருமுறை 3 மன உறுதி புள்ளிகளைத் திருப்பித் தரும் மருந்தை தயாரிக்கிறார்.",
