    "enemyPerk_undead": "முதல் மரணத்திற்குப் பிறகு ஒருமுறை 1 உயிர் புள்ளியுடன் மீண்டும் எழுகிறான்.",
    "enemyPerk_beast": "எப்போதும் எல்லைக்குள் உள்ள மிகவும் பலவீனமான இலக்கைத் தாக்குகிறான்.",
