    "enemyPerk_dragon": "ஒரு போருக்கு ஒருமுறை அவனது தீ மூச்சு ஒரு வரிசையிலுள்ள எல்லாக் கட்டங்களையும் தாக்கும்.",
    "enemyPerk_goblin": "குழுக்களாக வருகிறான்: அருகிலுள்ள ஒவ்வொரு கூடுதல் கோப்ளினும் +1 சேதம் தருகிறது.",
    "enemyPerk_giant": "அவனைப் பின்னால் தள்ள முடியாது; எதிரிகளை 2 கட்டங்கள் தொலைவில் வீசுகிறான்.",
    "enemyPerk_elemental": "மாயமற்ற ஆயுதங்களுக்கு எதிர்ப்புத் திறன் கொண்டவன்.",
    "enemyPerk_construct": "நஞ்சு மற்றும் அச்சத்திற்கு எதிர்ப்புத் திறன் கொண்டவன்.",
    "enemyPerk_bandit": "உயிர் புள்ளிகள் பாதிக்குக் குறைவானதும் தப்பி ஓடுகிறான்.",
