    "enemyAbility_3": "உயிர் புள்ளிகள் பாதிக்குக் குறைவானால் ஒரு கூட்டாளியை அழைக்கிறான்.",
    "enemyAbility_4": "தன்னைச் சுற்றியுள்ள எல்லாக் கட்டங்களையும் ஒரே நேரத்தில் தாக்குகிறான்.",
    "enemyAbility_5": "ஒவ்வொரு அடிக்குப் பிறகும் 1 உயிர் புள்ளியைக் குணப்படுத்திக் கொள்கிறான்.",
    "enemyAbility_6": "இலக்கின் கவச புள்ளிகளில் பாதியைப் புறக்கணிக்கிறான்.",
    "enemyAbility_7": "தடைகளையும் ஆறுகளையும் கடந்து நகர்கிறான்.",
    "enemyAbility_8": "முதலில் தாக்கினால் இரு மடங்கு சேதம் விளைவிக்கிறான்.",
